const response = $input.first();
const html = response.data || response.body || JSON.stringify(response);

if (!html || typeof html !== 'string') {
  return { error: 'No HTML data received', received: typeof html };
}

// Buscar el token CSRF usando múltiples patrones
let tokenMatch = html.match(/name=["']__RequestVerificationToken["'][^>]*value=["']([^"']+)["']/i);
if (!tokenMatch) {
  tokenMatch = html.match(/value=["']([^"']+)["'][^>]*name=["']__RequestVerificationToken["']/i);
}
if (!tokenMatch) {
  tokenMatch = html.match(/__RequestVerificationToken['"]\s*,?\s*value['"]\s*=\s*['"]([^'"]+)['"]/);
}
if (!tokenMatch) {
  tokenMatch = html.match(/__RequestVerificationToken.*?value="([^"]+)"/);
}

if (!tokenMatch || !tokenMatch[1]) {
  return { error: 'Token CSRF no encontrado', htmlLength: html.length };
}

return { csrfToken: tokenMatch[1] };

// Acceder a los datos en el formato correcto
const response = $input.first();
let html = response.data || response.body || response;

if (!html || typeof html !== 'string') {
  return { 
    success: false, 
    error: 'No se recibió HTML válido',
    received: typeof html,
    total: 0,
    incluidas: 0,
    excluidas: 0,
    polizas: [],
    debug: JSON.stringify(Object.keys(response)).substring(0, 200)
  };
}

// Buscar la tabla en el HTML
const tableMatch = html.match(/<table[^>]*>([\s\S]*?)<\/table>/);
if (!tableMatch) {
  return { 
    success: false, 
    error: 'Tabla no encontrada en el HTML',
    total: 0,
    incluidas: 0,
    excluidas: 0,
    polizas: []
  };
}

const polizas = [];
const excluidas = [];

// Expresión regular para extraer filas de tabla
const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/g;
let rowMatch;

while ((rowMatch = rowRegex.exec(tableMatch[1])) !== null) {
  const row = rowMatch[1];

  // Extraer celdas
  const cellRegex = /<td[^>]*>([\s\S]*?)<\/td>/g;
  const cells = [];
  let cellMatch;

  while ((cellMatch = cellRegex.exec(row)) !== null) {
    let content = cellMatch[1]
      .replace(/<[^>]*>/g, '') // Remover tags HTML
      .trim();
    cells.push(content);
  }

  if (cells.length < 6) continue;

  const ramo = cells[1] || '';
  const poliza = cells[2] || '';
  const endoso = cells[3] || '';
  const motivo = cells[5] || '';
  const productor = cells[6] || '';

  // Filtros de exclusión
  const motivos_excluir = ['Cambio forma de pago'];
  const productores_excluir = ['FASANELLA', 'LIJO', 'CALARCO', 'MAGNAGHI'];

  let excluir = false;

  if (motivos_excluir.some(m => motivo.toUpperCase().includes(m.toUpperCase()))) {
    excluir = true;
  }

  if (productores_excluir.some(p => productor.toUpperCase().includes(p.toUpperCase()))) {
    excluir = true;
  }

  if (!excluir && poliza) {
    polizas.push({
      ramo,
      poliza,
      endoso,
      productor,
      motivo
    });
  } else if (excluir && poliza) {
    excluidas.push({
      poliza,
      productor,
      razon: motivo
    });
  }
}

return {
  success: true,
  total: polizas.length + excluidas.length,
  incluidas: polizas.length,
  excluidas: excluidas.length,
  polizas: polizas,
  polizasExcluidas: excluidas
};
